377	    /// PopupManager owns non-grabbing trees independently of the seat's active
378	    /// PopupGrab. Detach every subtree when its root leaves the scene so a later
379	    /// remap cannot resurrect old popups. Collect before mutating the tree;
380	    /// dismiss_popup sends popup_done to descendants before their parent.
381	    fn dismiss_root_popups(surface: &WlSurface) {
382	        if !surface.alive() {
383	            return;
384	        }
385	        let popups: Vec<_> = PopupManager::popups_for_surface(surface)
386	            .map(|(popup, _)| popup)
387	            .collect();
388	        for popup in popups {
389	            // An earlier ancestor dismissal may already have detached this node.
390	            // The pinned manager treats an absent subtree as a no-op.
391	            let _ = PopupManager::dismiss_popup(surface, &popup);
